# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::Admission do
  # admit!(generation: nil) must never fence by accident, so an invalid value
  # is refused before anything is stored.
  it "admit! with an invalid generation raises and leaves the stored generation unchanged" do
    described_class.ensure_initial!
    described_class.admit!(generation: 2)

    [nil, 0, -1, "4", 4.0].each do |generation|
      expect { described_class.admit!(generation:) }.to raise_error(ArgumentError)
      expect(described_class.current.generation).to eq(2)
    end
  end
end

