require "rails_helper"

RSpec.describe Timekeeping::Admission do
  # The fence stays in place until a later admission
  it "ensure_initial! creates one row at generation 1 and never lifts an existing fence" do
    described_class.delete_all

    described_class.ensure_initial!
    expect(described_class.count).to eq(1)
    expect(described_class.current.generation).to eq(1)

    described_class.fence!(lock_timeout: 5)
    described_class.ensure_initial!

    expect(described_class.count).to eq(1)
    expect(described_class.current.generation).to be_nil
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::Admission, "fence! waiting on an admitted write" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # "Fencing waits for writes already admitted, with a lock timeout of 60 s in production use"
  it "fence! waits for a write already admitted on another connection, lets it commit, then fences" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    project = timekeeping_arrange.project(company:)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    patch = build_entry_command(:update, token: timekeeping_arrange.token_for(owner), entry_id:,
                                         body: { "note" => "Admitted before the fence" })
    reached = Queue.new
    release = Queue.new
    writer_pid = Queue.new
    fencer_pid = Queue.new
    checkpoint = lambda do |step|
      next unless step == :generation_checked

      reached << true
      release.pop
    end

    writer = Thread.new do
      ApplicationRecord.connection_pool.with_connection do |connection|
        writer_pid << connection.select_value("SELECT pg_backend_pid()")
        Timekeeping::EntryWriter.new(checkpoint:).call(patch)
      end
    end
    expect(reached.pop(timeout: 10)).to be(true)
    fencer = Thread.new do
      ApplicationRecord.connection_pool.with_connection do |connection|
        fencer_pid << connection.select_value("SELECT pg_backend_pid()")
        Timekeeping::Admission.fence!(lock_timeout: 10)
        :fenced
      end
    end

    holder = writer_pid.pop(timeout: 10)
    waiter = fencer_pid.pop(timeout: 10)
    deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + 3
    blocked = false
    until blocked || Process.clock_gettime(Process::CLOCK_MONOTONIC) > deadline
      blocked = ApplicationRecord.connection.select_value(
        ApplicationRecord.sanitize_sql_array(["SELECT ? = ANY(pg_blocking_pids(?))", holder, waiter])
      )
      sleep 0.02 unless blocked
    end
    release << true

    outcome = writer.join(10)&.value
    expect(blocked).to be(true), "fence! never waited on the admitted write's FOR SHARE lock"
    expect(outcome.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Admitted before the fence")
    expect(fencer.join(10)&.value).to eq(:fenced)
    expect(Timekeeping::Admission.current.generation).to be_nil
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::Admission, "fence! timing out on an admitted write" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # "`fence!` waits for a write already admitted in another connection to commit, and times out with a short injected lock timeout."
  it "fence! with a short lock timeout raises LockWaitTimeout and leaves the generation admitted" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    project = timekeeping_arrange.project(company:)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    patch = build_entry_command(:update, token: timekeeping_arrange.token_for(owner), entry_id:,
                                         body: { "note" => "Held" })
    reached = Queue.new
    release = Queue.new
    checkpoint = lambda do |step|
      next unless step == :generation_checked

      reached << true
      release.pop
    end

    writer = Thread.new do
      ApplicationRecord.connection_pool.with_connection { Timekeeping::EntryWriter.new(checkpoint:).call(patch) }
    end
    expect(reached.pop(timeout: 10)).to be(true)
    fence_error = Thread.new do
      ApplicationRecord.connection_pool.with_connection do
        Timekeeping::Admission.fence!(lock_timeout: 0.2)
        nil
      rescue StandardError => e
        e
      end
    end.join(10)&.value
    release << true

    expect(fence_error).to be_a(ActiveRecord::LockWaitTimeout)
    expect(writer.join(10)&.value&.status).to eq(200)
    expect(Timekeeping::Admission.current.generation).to eq(1)
  end
end

