RSpec.describe Timekeeping::Admission, "fence and admit on the single row" do
  it "fences after an admission and keeps the fence until the next admit!" do
    described_class.admit!(generation: 2)
    described_class.fence!(lock_timeout: 1)
    expect(described_class.current.generation).to be_nil

    described_class.fence!(lock_timeout: 1)
    expect(described_class.current.generation).to be_nil

    described_class.admit!(generation: 3)
    expect(described_class.current.generation).to eq(3)
  end

  # The example's transaction is still open after fence!, so SET LOCAL is
  # still visible here.
  it "fences with the 60 second lock timeout when none is given" do
    described_class.fence!

    expect(ApplicationRecord.connection.select_value("SHOW lock_timeout")).to eq("1min")
    expect(described_class.current.generation).to be_nil
  end

  it "refuses a second row" do
    expect { described_class.insert_all!([{ id: 2 }]) }.to raise_error(ActiveRecord::StatementInvalid, /admission_single_row_check/)
  end
end
